// 排程巡檢 2026-11-16（patrol66）：理事長過世、換理事長、大會／理事會未依規定召開、理事N人出席M人、會員代表大會差別、地政士；條文已對 statutes.json.gz 核對
const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['理事長死了怎麼辦','一個月內補選'],['理事長往生','一個月內補選'],['理事長過世了怎麼辦','一個月內補選'],['理事長出缺怎麼辦','一個月內補選'],['理事長去世要補選嗎','一個月內補選'],
['我們協會想換理事長要怎麼做','任期屆滿就改選'],['怎麼換理事長','任期屆滿就改選'],['協會要換理事長流程','任期屆滿就改選'],['理事長可以換人嗎怎麼換','任期屆滿就改選'],
['不依規定招開大會','先分清是「沒開」'],['會員大會沒有依規定召開怎麼辦','先分清是「沒開」'],['協會沒照章程開會員大會','先分清是「沒開」'],['大會不照規定召開可以嗎','先分清是「沒開」'],
['理事會不依規定召開怎麼辦','每六個月至少一次'],['監事會沒有按規定開會','每六個月至少一次'],
['理事9人出席4人可以開會嗎','不能開會，至少要5人出席'],['理事15人出席8人可以開會嗎','可以開會，15人的過半數是8人'],['監事三人出席兩人可以開會嗎','可以開會'],['理事7人來了3人可以開會嗎','不能開會，至少要4人出席'],
['會員代表大會跟會員大會差在哪','分區選出代表'],['會員代表大會和會員大會有什麼不同','分區選出代表'],['代表大會與會員大會差別','分區選出代表'],
['地政士','地政士法辦理'],['地政士法','地政士法辦理'],['地政士執業登記','地政士法辦理'],
];
const pat=/一個月內補選；剩下任期|任期屆滿就改選|先分清是「沒開」|每六個月至少一次；理事長無故|人的過半數是|至少要\d+人出席|分區選出代表來開|地政士本身的執業/;
const no=[
 // 交既有規則或知識庫
 '理事長辭職怎麼辦','理事長可以中途換人嗎','理事長可以單方面撤換理事嗎','換理事長要準備什麼文件','換理事長銀行印鑑要改嗎','理事長可以連任幾次','理事長罷免怎麼辦','理事長過世遺產怎麼辦','理事長出缺剩半年要補選嗎',
 '合作社理事主席過世','公會理事長過世','合作社想換理事主席','合作社理事7人出席3人可以開會嗎',
 '會員大會通知要幾天前寄','理事會幾天前通知','大會沒有開會怎麼辦','會員大會委託書不合規定怎麼辦','理事會開會通知書怎麼寫',
 '理事9人只有4人出席可以開會嗎','理事9人，只有4名出席，可以開會嗎','理事會要幾人出席','理事9人出缺2人剩7人要幾人出席','會員大會出席4人可以開會嗎',
 '會員代表大會怎麼開','會員大會跟會員代表大會通知要幾天','會員代表大會要多少人出席',
 '地政士公會','地政士公會怎麼改選','地政士可以拒絕入會嗎','地政士公會承辦電話',
];
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
// Issue #35：normalizeQuestion 去掉「社區發展協會的」前綴，讓知識庫既有答案接得到
for(const [q,w] of [['社區發展協會的活動中心可以借給別人嗎','社區活動中心可以借給別人嗎'],['我們協會的活動中心可以出租嗎','社區活動中心可以出租嗎']]){const n=r.normalizeQuestion(q);if(n!==w){console.error('NORM',q,'=>',n);bad++;}}
if(bad)throw new Error('patrol66 failed '+bad);console.log('ok');
